export { BlockEditor } from "./block-editor";
export { useBlockEditorContext } from "./context";
export { BubbleMenu } from "./bubble-menu/index";
export {
  SlashCommand,
  getSlashCommandSuggestion,
  defaultSlashCommandItems,
} from "./extensions";
export { CodeBlock } from "./extensions/code-block";
export type { SlashCommandSuggestionItem, OnCommandSelect } from "./extensions";
export type { BlockEditorProps, BlockEditorLabels } from "./types";
export { DEFAULT_BLOCK_EDITOR_LABELS } from "./labels";
export type { BlockEditorIcons } from "./icons";
export { DEFAULT_ICONS, DEFAULT_LANGUAGE_ICONS } from "./icons";

import { DragHandle } from "@tiptap/extension-drag-handle-react";
import type { Node } from "@tiptap/pm/model";
import { EditorContent } from "@tiptap/react";
import { Plus } from "lucide-react";
import { useCallback, useRef } from "react";

import { BubbleMenu } from "./bubble-menu";
import { BlockEditorProvider, useBlockEditorContext } from "./context";
import { cn } from "./lib/utils";
import type { BlockEditorProps } from "./types";

const BlockEditorDragHandle = () => {
  const { editor, icons } = useBlockEditorContext();
  const dragNodeRef = useRef<{ node: Node; pos: number } | null>(null);

  const handleAdd = useCallback(() => {
    const dragNode = dragNodeRef.current;
    if (!dragNode || !editor || editor.isDestroyed) {
      return;
    }

    const { node, pos } = dragNode;
    if (node.type.spec.code || node.isLeaf) {
      return;
    }

    editor
      .chain()
      .focus(pos + 1)
      .insertContent("/")
      .run();
  }, [editor]);

  if (!editor) {
    return null;
  }

  return (
    <DragHandle
      computePositionConfig={{ placement: "left-start", strategy: "absolute" }}
      editor={editor}
      onNodeChange={({ node, pos }) => {
        dragNodeRef.current = node ? { node, pos } : null;
      }}
    >
      <button
        type="button"
        aria-label="Add block"
        className="block-editor-add-block"
        onClick={handleAdd}
        onDragStart={(event) => event.preventDefault()}
      >
        <Plus />
      </button>
      {icons.dragHandleIcon}
    </DragHandle>
  );
};

const BlockEditorContent = () => {
  const { editor } = useBlockEditorContext();

  return (
    <div className="block-editor">
      {editor && editor.isEditable && <BlockEditorDragHandle />}
      {editor && editor.isEditable && <BubbleMenu editor={editor} />}
      <EditorContent editor={editor} className="block-editor-content" />
    </div>
  );
};

const BlockEditorRoot = ({
  editor,
  children,
  className,
  labels,
  icons,
}: BlockEditorProps) => (
  <BlockEditorProvider editor={editor} labels={labels} icons={icons}>
    <div className={cn("block-editor", className)}>
      {children ?? <BlockEditorContent />}
    </div>
  </BlockEditorProvider>
);

export const BlockEditor = Object.assign(BlockEditorRoot, {
  BubbleMenu,
  Content: BlockEditorContent,
});

import { isTextSelection } from "@tiptap/core";
import type { Editor } from "@tiptap/react";
import { BubbleMenu as TiptapBubbleMenu } from "@tiptap/react/menus";
import { useState, useCallback } from "react";

import { DEFAULT_ICONS } from "../icons";
import { BubbleButton, BubbleSeparator } from "../ui";
import { TextAlignSelector } from "./align-selector";
import { LanguageSelector } from "./language-selector";
import { LinkSelector } from "./link-selector";
import { NodeSelector } from "./node-selector";
import { TextButtons } from "./text-buttons";
import { useEditorState, shallowEqual } from "./utils";

export interface BubbleMenuProps {
  editor: Editor | null;
}

export const BubbleMenu = ({ editor }: BubbleMenuProps) => {
  const [copied, setCopied] = useState(false);
  const editorState = useEditorState(
    editor,
    (ed) => ({
      isCodeBlock: ed.isActive("codeBlock"),
    }),
    shallowEqual
  );

  const shouldShow = useCallback(
    ({
      editor: ed,
      state,
    }: {
      editor: Editor;
      state: { selection: { empty: boolean } };
    }) => {
      const { selection } = state;
      if (!ed.isEditable) {
        return false;
      }
      if (selection.empty && !ed.isActive("codeBlock")) {
        return false;
      }
      if (!selection.empty && !isTextSelection(selection)) {
        return false;
      }
      return true;
    },
    []
  );

  if (!editor) {
    return null;
  }

  const hasTextAlign = editor.extensionManager.extensions.some(
    (ext) => ext.name === "textAlign"
  );

  const isCodeBlockActive = editorState.isCodeBlock;

  return (
    <TiptapBubbleMenu
      editor={editor}
      options={{ offset: 8, placement: "top" }}
      shouldShow={shouldShow}
    >
      <div className="block-editor-bubble-menu">
        {isCodeBlockActive ? (
          <>
            <NodeSelector editor={editor} />
            <BubbleSeparator />
            <LanguageSelector editor={editor} />
            <BubbleSeparator />
            <BubbleButton
              onMouseDown={(e) => e.preventDefault()}
              onClick={async () => {
                const { from, to } = editor.state.selection;
                const text = editor.state.doc.textBetween(from, to, "\n");
                try {
                  await navigator.clipboard.writeText(text);
                  setCopied(true);
                  setTimeout(() => setCopied(false), 2000);
                } catch {
                  /* ignored */
                }
              }}
            >
              <span
                className={`block-editor-copy-icon${copied ? " block-editor-copy-icon--copied" : ""}`}
              >
                {copied ? DEFAULT_ICONS.checkIcon : DEFAULT_ICONS.copyIcon}
              </span>
            </BubbleButton>
          </>
        ) : (
          <>
            <NodeSelector editor={editor} />
            <BubbleSeparator />
            <TextButtons editor={editor} />
            <BubbleSeparator />
            <LinkSelector editor={editor} />
            {hasTextAlign && (
              <>
                <BubbleSeparator />
                <TextAlignSelector editor={editor} />
              </>
            )}
          </>
        )}
      </div>
    </TiptapBubbleMenu>
  );
};

import type { Editor } from "@tiptap/react";
import { useCallback, useEffect, useRef, useSyncExternalStore } from "react";

const defaultEqual = <T>(a: T, b: T) => a === b;

export const shallowEqual = <T extends Record<string, unknown>>(
  a: T,
  b: T
): boolean => {
  if (a === b) {
    return true;
  }
  if (!a || !b) {
    return false;
  }
  const ak = Object.keys(a);
  const bk = Object.keys(b);
  if (ak.length !== bk.length) {
    return false;
  }
  return ak.every((k) => a[k] === b[k]);
};

export const useEditorState = <T>(
  editor: Editor | null,
  selector: (e: Editor) => T,
  isEqual: (a: T, b: T) => boolean = defaultEqual
): T => {
  const selectorRef = useRef(selector);
  const isEqualRef = useRef(isEqual);

  useEffect(() => {
    selectorRef.current = selector;
    isEqualRef.current = isEqual;
  });

  const snapshotRef = useRef<{ value: T }>({
    value: editor ? selector(editor) : (undefined as unknown as T),
  });

  const updateSnapshot = useCallback(() => {
    if (!editor) {
      return;
    }
    const next = selectorRef.current(editor);
    if (
      snapshotRef.current &&
      isEqualRef.current(snapshotRef.current.value, next)
    ) {
      return;
    }
    snapshotRef.current = { value: next };
  }, [editor]);

  const subscribe = useCallback(
    (onStoreChange: () => void) => {
      if (!editor) {
        return () => {
          // noop
        };
      }
      const update = () => {
        updateSnapshot();
        onStoreChange();
      };
      editor.on("selectionUpdate", update);
      editor.on("transaction", update);
      return () => {
        editor.off("selectionUpdate", update);
        editor.off("transaction", update);
      };
    },
    [editor, updateSnapshot]
  );

  const getSnapshot = useCallback((): T => snapshotRef.current.value, []);

  return useSyncExternalStore(subscribe, getSnapshot, getSnapshot);
};

export const copyBlock = async (editor: Editor): Promise<void> => {
  const { from } = editor.state.selection;
  const $from = editor.state.doc.resolve(from);
  const start = $from.before($from.depth);
  const end = $from.after($from.depth);
  if (start < 0 || end <= start) {
    return;
  }
  const text = editor.state.doc.textBetween(start, end, "\n", "\n");
  try {
    await navigator.clipboard.writeText(text);
  } catch {
    /* ignored */
  }
};

export const deleteBlock = (editor: Editor): void => {
  const { from } = editor.state.selection;
  const $from = editor.state.doc.resolve(from);
  const { depth } = $from;
  const start = $from.before(depth);
  const end = $from.after(depth);
  if (start < 0 || end <= start) {
    return;
  }
  editor.chain().focus().deleteRange({ from: start, to: end }).run();
};

