import type { Editor } from "@tiptap/react";
import { useState } from "react";

import { DEFAULT_ICONS, HeadingIcon } from "../icons";
import {
  BubbleButton,
  BubbleDropdown,
  BubbleDropdownDivider,
  BubbleDropdownIcon,
  BubbleDropdownItem,
  DropdownOverlay,
} from "../ui";
import { useEditorState, copyBlock, deleteBlock, shallowEqual } from "./utils";

interface SelectorResult {
  isParagraph: boolean;
  isHeading1: boolean;
  isHeading2: boolean;
  isHeading3: boolean;
  isBulletList: boolean;
  isOrderedList: boolean;
  isTaskList: boolean;
  isBlockquote: boolean;
  isCodeBlock: boolean;
}

interface NodeItem {
  command: (editor: Editor) => void;
  icon: React.ReactNode;
  isActive: (state: SelectorResult) => boolean;
  name: string;
}

interface NodeChain {
  run(): boolean;
  setParagraph(): NodeChain;
  toggleBlockquote(): NodeChain;
  toggleBulletList(): NodeChain;
  toggleCodeBlock(): NodeChain;
  toggleHeading(options: { level: number }): NodeChain;
  toggleOrderedList(): NodeChain;
  toggleTaskList(): NodeChain;
}

const nodeItems: NodeItem[] = [
  {
    command: (e) =>
      (e.chain().focus() as unknown as NodeChain).setParagraph().run(),
    icon: DEFAULT_ICONS.slashTextIcon,
    isActive: (s) =>
      s.isParagraph &&
      !s.isBulletList &&
      !s.isOrderedList &&
      !s.isTaskList &&
      !s.isBlockquote &&
      !s.isCodeBlock,
    name: "Text",
  },
  {
    command: (e) =>
      (e.chain().focus() as unknown as NodeChain)
        .toggleHeading({ level: 1 })
        .run(),
    icon: <HeadingIcon level={1} />,
    isActive: (s) => s.isHeading1,
    name: "Heading 1",
  },
  {
    command: (e) =>
      (e.chain().focus() as unknown as NodeChain)
        .toggleHeading({ level: 2 })
        .run(),
    icon: <HeadingIcon level={2} />,
    isActive: (s) => s.isHeading2,
    name: "Heading 2",
  },
  {
    command: (e) =>
      (e.chain().focus() as unknown as NodeChain)
        .toggleHeading({ level: 3 })
        .run(),
    icon: <HeadingIcon level={3} />,
    isActive: (s) => s.isHeading3,
    name: "Heading 3",
  },
  {
    command: (e) =>
      (e.chain().focus() as unknown as NodeChain).toggleBulletList().run(),
    icon: DEFAULT_ICONS.slashBulletListIcon,
    isActive: (s) => s.isBulletList,
    name: "Bullet List",
  },
  {
    command: (e) =>
      (e.chain().focus() as unknown as NodeChain).toggleOrderedList().run(),
    icon: DEFAULT_ICONS.slashOrderedListIcon,
    isActive: (s) => s.isOrderedList,
    name: "Numbered List",
  },
  {
    command: (e) =>
      (e.chain().focus() as unknown as NodeChain).toggleTaskList().run(),
    icon: DEFAULT_ICONS.slashTaskListIcon,
    isActive: (s) => s.isTaskList,
    name: "To-do List",
  },
  {
    command: (e) =>
      (e.chain().focus() as unknown as NodeChain).toggleBlockquote().run(),
    icon: DEFAULT_ICONS.slashBlockquoteIcon,
    isActive: (s) => s.isBlockquote,
    name: "Quote",
  },
  {
    command: (e) =>
      (e.chain().focus() as unknown as NodeChain).toggleCodeBlock().run(),
    icon: DEFAULT_ICONS.slashCodeBlockIcon,
    isActive: (s) => s.isCodeBlock,
    name: "Code Block",
  },
];

export const NodeSelector = ({ editor }: { editor: Editor }) => {
  const [open, setOpen] = useState(false);
  const editorState = useEditorState(
    editor,
    (ed) => ({
      isBlockquote: ed.isActive("blockquote"),
      isBulletList: ed.isActive("bulletList"),
      isCodeBlock: ed.isActive("codeBlock"),
      isHeading1: ed.isActive("heading", { level: 1 }),
      isHeading2: ed.isActive("heading", { level: 2 }),
      isHeading3: ed.isActive("heading", { level: 3 }),
      isOrderedList: ed.isActive("orderedList"),
      isParagraph: ed.isActive("paragraph"),
      isTaskList: ed.isActive("taskList"),
    }),
    shallowEqual
  );

  const activeItems = nodeItems.filter((i) => i.isActive(editorState));
  const activeName =
    activeItems.length > 1 ? "Multiple" : (activeItems[0]?.name ?? "Text");
  const activeIcon = activeItems.length === 1 ? activeItems[0]?.icon : null;

  return (
    <div style={{ position: "relative" }}>
      <BubbleButton
        onMouseDown={(e) => e.preventDefault()}
        onClick={() => setOpen(!open)}
      >
        {activeIcon && <BubbleDropdownIcon>{activeIcon}</BubbleDropdownIcon>}
        <span className="block-editor-bubble-btn-text">{activeName}</span>
        {DEFAULT_ICONS.dropdownArrowIcon}
      </BubbleButton>
      {open && (
        <>
          <DropdownOverlay
            onClick={() => setOpen(false)}
            onKeyDown={(e) => {
              if (e.key === "Escape") {
                setOpen(false);
              }
            }}
          />
          <BubbleDropdown>
            {nodeItems.map((item, i) => (
              <BubbleDropdownItem
                key={i}
                active={item.isActive(editorState)}
                onMouseDown={(e) => e.preventDefault()}
                onClick={() => {
                  item.command(editor);
                  setOpen(false);
                }}
              >
                <BubbleDropdownIcon>{item.icon}</BubbleDropdownIcon>
                <span>{item.name}</span>
              </BubbleDropdownItem>
            ))}
            <BubbleDropdownDivider />
            <BubbleDropdownItem
              onMouseDown={(e) => e.preventDefault()}
              onClick={() => {
                copyBlock(editor);
                setOpen(false);
              }}
            >
              <BubbleDropdownIcon>{DEFAULT_ICONS.copyIcon}</BubbleDropdownIcon>
              <span>Copy</span>
            </BubbleDropdownItem>
            <BubbleDropdownItem
              danger
              onMouseDown={(e) => e.preventDefault()}
              onClick={() => {
                deleteBlock(editor);
                setOpen(false);
              }}
            >
              <BubbleDropdownIcon>
                {DEFAULT_ICONS.deleteIcon}
              </BubbleDropdownIcon>
              <span>Delete</span>
            </BubbleDropdownItem>
          </BubbleDropdown>
        </>
      )}
    </div>
  );
};

import type { Editor } from "@tiptap/react";

import { DEFAULT_ICONS } from "../icons";
import { BubbleButton, BubbleButtonGroup } from "../ui";
import { useEditorState, shallowEqual } from "./utils";

interface TextSelectorResult {
  isBold: boolean;
  isItalic: boolean;
  isUnderline: boolean;
  isStrike: boolean;
  isCode: boolean;
}

interface ToggleableChain {
  run(): boolean;
  toggleBold(): ToggleableChain;
  toggleCode(): ToggleableChain;
  toggleItalic(): ToggleableChain;
  toggleStrike(): ToggleableChain;
  toggleUnderline(): ToggleableChain;
}

const textItems = [
  {
    command: (e: Editor) =>
      (e.chain().focus() as unknown as ToggleableChain).toggleBold().run(),
    icon: DEFAULT_ICONS.boldIcon,
    isActive: (s: TextSelectorResult) => s.isBold,
  },
  {
    command: (e: Editor) =>
      (e.chain().focus() as unknown as ToggleableChain).toggleItalic().run(),
    icon: DEFAULT_ICONS.italicIcon,
    isActive: (s: TextSelectorResult) => s.isItalic,
  },
  {
    command: (e: Editor) =>
      (e.chain().focus() as unknown as ToggleableChain).toggleUnderline().run(),
    icon: DEFAULT_ICONS.underlineIcon,
    isActive: (s: TextSelectorResult) => s.isUnderline,
  },
  {
    command: (e: Editor) =>
      (e.chain().focus() as unknown as ToggleableChain).toggleStrike().run(),
    icon: DEFAULT_ICONS.strikethroughIcon,
    isActive: (s: TextSelectorResult) => s.isStrike,
  },
  {
    command: (e: Editor) =>
      (e.chain().focus() as unknown as ToggleableChain).toggleCode().run(),
    icon: DEFAULT_ICONS.codeIcon,
    isActive: (s: TextSelectorResult) => s.isCode,
  },
];

export const TextButtons = ({ editor }: { editor: Editor }) => {
  const editorState = useEditorState(
    editor,
    (ed) => ({
      isBold: ed.isActive("bold"),
      isCode: ed.isActive("code"),
      isItalic: ed.isActive("italic"),
      isStrike: ed.isActive("strike"),
      isUnderline: ed.isActive("underline"),
    }),
    shallowEqual
  );

  return (
    <BubbleButtonGroup>
      {textItems.map((item, i) => (
        <BubbleButton
          key={i}
          active={item.isActive(editorState)}
          onMouseDown={(e) => e.preventDefault()}
          onClick={() => item.command(editor)}
        >
          {item.icon}
        </BubbleButton>
      ))}
    </BubbleButtonGroup>
  );
};

import type { Editor } from "@tiptap/react";
import { useState } from "react";

import { DEFAULT_ICONS } from "../icons";
import {
  BubbleButton,
  BubbleDropdown,
  BubbleDropdownIcon,
  BubbleDropdownItem,
  DropdownOverlay,
} from "../ui";
import { useEditorState, shallowEqual } from "./utils";

interface AlignSelectorResult {
  isAlignLeft: boolean;
  isAlignCenter: boolean;
  isAlignRight: boolean;
}

interface AlignableChain {
  run(): boolean;
  setTextAlign(alignment: "center" | "left" | "right"): AlignableChain;
}

const alignItems = [
  {
    command: (e: Editor) =>
      (e.chain().focus() as unknown as AlignableChain)
        .setTextAlign("left")
        .run(),
    icon: DEFAULT_ICONS.alignLeftIcon,
    isActive: (s: AlignSelectorResult) => s.isAlignLeft,
    label: "Left",
  },
  {
    command: (e: Editor) =>
      (e.chain().focus() as unknown as AlignableChain)
        .setTextAlign("center")
        .run(),
    icon: DEFAULT_ICONS.alignCenterIcon,
    isActive: (s: AlignSelectorResult) => s.isAlignCenter,
    label: "Center",
  },
  {
    command: (e: Editor) =>
      (e.chain().focus() as unknown as AlignableChain)
        .setTextAlign("right")
        .run(),
    icon: DEFAULT_ICONS.alignRightIcon,
    isActive: (s: AlignSelectorResult) => s.isAlignRight,
    label: "Right",
  },
];

export const TextAlignSelector = ({ editor }: { editor: Editor }) => {
  const [open, setOpen] = useState(false);
  const editorState = useEditorState(
    editor,
    (ed) => ({
      isAlignCenter: ed.isActive({ textAlign: "center" }),
      isAlignLeft:
        !ed.isActive({ textAlign: "center" }) &&
        !ed.isActive({ textAlign: "right" }),
      isAlignRight: ed.isActive({ textAlign: "right" }),
    }),
    shallowEqual
  );

  const activeItem = alignItems.find((i) => i.isActive(editorState));

  return (
    <div style={{ position: "relative" }}>
      <BubbleButton
        onMouseDown={(e) => e.preventDefault()}
        onClick={() => setOpen(!open)}
      >
        <BubbleDropdownIcon>
          {activeItem ? activeItem.icon : DEFAULT_ICONS.alignLeftIcon}
        </BubbleDropdownIcon>
        {DEFAULT_ICONS.dropdownArrowIcon}
      </BubbleButton>
      {open && (
        <>
          <DropdownOverlay
            onClick={() => setOpen(false)}
            onKeyDown={(e) => {
              if (e.key === "Escape") {
                setOpen(false);
              }
            }}
          />
          <BubbleDropdown align="align" style={{ left: "auto", right: 0 }}>
            {alignItems.map((item, i) => (
              <BubbleDropdownItem
                key={i}
                active={item.isActive(editorState)}
                onMouseDown={(e) => e.preventDefault()}
                onClick={() => {
                  item.command(editor);
                  setOpen(false);
                }}
              >
                <BubbleDropdownIcon>{item.icon}</BubbleDropdownIcon>
                <span>{item.label}</span>
              </BubbleDropdownItem>
            ))}
          </BubbleDropdown>
        </>
      )}
    </div>
  );
};

import type { Editor } from "@tiptap/react";
import { useState, useRef, useCallback, useEffect } from "react";

import { DEFAULT_ICONS } from "../icons";
import {
  BubbleButton,
  BubbleDropdown,
  BubbleDropdownIcon,
  BubbleDropdownItem,
  DropdownOverlay,
} from "../ui";

interface LinkableChain {
  extendMarkRange(type: string): LinkableChain;
  run(): boolean;
  setLink(options: { href: string }): LinkableChain;
  unsetLink(): LinkableChain;
}

export const LinkSelector = ({ editor }: { editor: Editor }) => {
  const [open, setOpen] = useState(false);
  const inputRef = useRef<HTMLInputElement>(null);
  const [{ isLink, linkUrl }, setLinkState] = useState(() => ({
    isLink: editor.isActive("link"),
    linkUrl: editor.getAttributes("link").href || "",
  }));

  useEffect(() => {
    const update = () => {
      setLinkState({
        isLink: editor.isActive("link"),
        linkUrl: editor.getAttributes("link").href || "",
      });
    };
    editor.on("selectionUpdate", update);
    editor.on("transaction", update);
    return () => {
      editor.off("selectionUpdate", update);
      editor.off("transaction", update);
    };
  }, [editor]);

  const handleSubmit = useCallback(
    (evt: React.FormEvent) => {
      evt.preventDefault();
      let url = inputRef.current?.value?.trim();
      if (!url) {
        return;
      }
      if (!/^https?:\/\//i.test(url)) {
        url = `https://${url}`;
      }
      (editor.chain().focus() as unknown as LinkableChain)
        .extendMarkRange("link")
        .setLink({ href: url })
        .run();
      setOpen(false);
    },
    [editor]
  );

  const handleUnlink = useCallback(() => {
    (editor.chain().focus() as unknown as LinkableChain).unsetLink().run();
    setOpen(false);
  }, [editor]);

  return (
    <div style={{ position: "relative" }}>
      <BubbleButton
        active={isLink}
        onMouseDown={(e) => e.preventDefault()}
        onClick={() => setOpen(!open)}
        title="Link"
      >
        {DEFAULT_ICONS.linkIcon}
      </BubbleButton>
      {open && (
        <>
          <DropdownOverlay
            onClick={() => setOpen(false)}
            onKeyDown={(e) => {
              if (e.key === "Escape") {
                setOpen(false);
              }
            }}
          />
          <BubbleDropdown style={{ left: "auto", minWidth: "220px", right: 0 }}>
            <form className="block-editor-link-form" onSubmit={handleSubmit}>
              <input
                ref={inputRef}
                type="text"
                className="block-editor-link-input"
                placeholder="Paste a link..."
                defaultValue={linkUrl}
                autoFocus
              />
              <div className="block-editor-link-actions">
                {isLink && (
                  <BubbleDropdownItem
                    danger
                    onMouseDown={(e) => e.preventDefault()}
                    onClick={handleUnlink}
                    style={{ justifyContent: "center" }}
                  >
                    <BubbleDropdownIcon>
                      {DEFAULT_ICONS.unlinkIcon}
                    </BubbleDropdownIcon>
                    <span>Remove</span>
                  </BubbleDropdownItem>
                )}
                <BubbleDropdownItem
                  onMouseDown={(e) => e.preventDefault()}
                  type="submit"
                  style={{ justifyContent: "center" }}
                >
                  <BubbleDropdownIcon>
                    {DEFAULT_ICONS.checkIcon}
                  </BubbleDropdownIcon>
                  <span>{isLink ? "Update" : "Add"}</span>
                </BubbleDropdownItem>
              </div>
            </form>
          </BubbleDropdown>
        </>
      )}
    </div>
  );
};

import type { Editor } from "@tiptap/react";
import { useState } from "react";

import { useBlockEditorContext } from "../context";
import { DEFAULT_ICONS } from "../icons";
import {
  BubbleButton,
  BubbleDropdown,
  BubbleDropdownIcon,
  BubbleDropdownItem,
  DropdownOverlay,
} from "../ui";
import {
  CODE_BLOCK_LANGUAGES,
  getLanguageLabel,
  useEditorState,
  shallowEqual,
} from "./utils";

export const LanguageSelector = ({ editor }: { editor: Editor }) => {
  const [open, setOpen] = useState(false);
  const { icons } = useBlockEditorContext();

  const { currentLanguage } = useEditorState(
    editor,
    (ed) => ({
      currentLanguage: ed.getAttributes("codeBlock").language || "javascript",
    }),
    shallowEqual
  );

  const langIcon =
    icons.languageIcons[currentLanguage] ?? icons.codeBlockLanguageIcon;

  return (
    <div style={{ position: "relative" }}>
      <BubbleButton
        onMouseDown={(e) => e.preventDefault()}
        onClick={() => setOpen(!open)}
      >
        <BubbleDropdownIcon>{langIcon}</BubbleDropdownIcon>
        <span className="block-editor-bubble-btn-text">
          {getLanguageLabel(currentLanguage)}
        </span>
        {DEFAULT_ICONS.dropdownArrowIcon}
      </BubbleButton>
      {open && (
        <>
          <DropdownOverlay
            onClick={() => setOpen(false)}
            onKeyDown={(e) => {
              if (e.key === "Escape") {
                setOpen(false);
              }
            }}
          />
          <BubbleDropdown align="language" style={{ left: "auto", right: 0 }}>
            {CODE_BLOCK_LANGUAGES.map((lang) => (
              <BubbleDropdownItem
                key={lang}
                active={currentLanguage === lang}
                onMouseDown={(e) => e.preventDefault()}
                onClick={() => {
                  editor
                    .chain()
                    .focus()
                    .updateAttributes("codeBlock", { language: lang })
                    .run();
                  setOpen(false);
                }}
              >
                <BubbleDropdownIcon>
                  {icons.languageIcons[lang] ?? icons.codeBlockLanguageIcon}
                </BubbleDropdownIcon>
                <span>{getLanguageLabel(lang)}</span>
              </BubbleDropdownItem>
            ))}
          </BubbleDropdown>
        </>
      )}
    </div>
  );
};

import type { Editor } from "@tiptap/core";
import { createContext, useContext } from "react";
import type { ReactNode } from "react";

import type { BlockEditorIcons } from "./icons";
import { DEFAULT_ICONS } from "./icons";
import { DEFAULT_BLOCK_EDITOR_LABELS } from "./labels";
import type { BlockEditorContextValue, BlockEditorLabels } from "./types";

const BlockEditorContext = createContext<BlockEditorContextValue | null>(null);

export const useBlockEditorContext = () => {
  const ctx = useContext(BlockEditorContext);
  if (!ctx) {
    throw new Error("BlockEditor components must be used within <BlockEditor>");
  }
  return ctx;
};

export interface BlockEditorProviderProps {
  editor: Editor | null;
  children: ReactNode;
  labels?: Partial<BlockEditorLabels>;
  icons?: Partial<BlockEditorIcons>;
}

export const BlockEditorProvider = ({
  editor,
  children,
  labels,
  icons,
}: BlockEditorProviderProps) => {
  const mergedLabels = { ...DEFAULT_BLOCK_EDITOR_LABELS, ...labels };
  const mergedIcons = { ...DEFAULT_ICONS, ...icons };

  return (
    <BlockEditorContext.Provider
      value={{
        editor,
        icons: mergedIcons,
        labels: mergedLabels,
      }}
    >
      {children}
    </BlockEditorContext.Provider>
  );
};

