}

/* Tiptap drag handle (from @tiptap/extension-drag-handle-react) */
.drag-handle {
  display: flex;
  align-items: center;
  gap: 0.12rem;
  height: 1.5rem;
  border-radius: calc(var(--radius) - 4px);
  background: transparent;
  color: var(--muted-foreground);
  cursor: grab;
  transition:
    background-color 150ms ease-out,
    color 150ms ease-out,
    opacity 150ms ease-out,
    transform 100ms ease-out,
    top 150ms ease-out,
    left 150ms ease-out;
  opacity: 0;
}

.drag-handle:hover {
  opacity: 1;
}

.drag-handle:active {
  cursor: grabbing;
  transform: scale(0.9);
}

.block-editor-content .ProseMirror:hover ~ .drag-handle,
.block-editor-content:hover .drag-handle {
  opacity: 1;
}

.block-editor-add-block {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 1.125rem;
  height: 1.125rem;
  padding: 0;
  border: none;
  border-radius: calc(var(--radius) - 4px);
  background: transparent;
  color: inherit;
  cursor: pointer;
  transition:
    background-color 100ms ease-out,
    color 100ms ease-out,
    transform 100ms ease-out;
}

.block-editor-add-block:hover {
  background: var(--accent);
  color: var(--accent-foreground);
}

.block-editor-add-block:active {
